import { Component, createMemo, For, Show } from "solid-js";

import { ChooserItem } from "#core/ui-next/components/chooser-item.jsx";
import { TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";

import { AdvisorRecommendationsList } from "#base/ui-next/components/advisor-recommendation.jsx";
import { TechCivicTooltip } from "#base/ui-next/tooltips/tech-civic-tooltip.jsx";

import type { TechNode } from "./tech-chooser.jsx";

interface TechChooserItemProps {
	node: TechNode;
	onSelect: (id: ProgressionTreeNodeType) => void;
}

export const TechChooserItem: Component<TechChooserItemProps> = (props) => {
	const pctLabel = createMemo(() => `${props.node.progress ?? 0}%`);
	// Get only the unlocks for the current depth being researched
	const currentDepthUnlocks = createMemo(() => {
		const depthIndex = props.node.currentDepthIndex ?? 0;
		return props.node.unlocksByDepth[depthIndex]?.unlocks ?? [];
	});
	return (
		<TechCivicTooltip
			node={{
				name: props.node.name,
				unlocksByDepth: props.node.unlocksByDepth,
				cost: props.node.cost,
				recommendations: props.node.recommendations,
				currentDepthIndex: props.node.currentDepthIndex,
			}}
			isCulture={false}
			initialVPosition={TooltipVerticalPosition.CENTER}
			initialHPosition={TooltipHorizontalPosition.RIGHT}
		>
			<ChooserItem
				name="TechChooserItem"
				class="tech-item self-stretch my-1\.25 text-accent-2 pointer-events-auto"
				icon={props.node.icon}
				selectOnActivate
				audio={{
					group: "audio-screen-tech-tree-chooser",
					onFocus: "data-audio-chooser-focus",
					onActivate: "data-audio-chooser-activate",
				}}
				onActivate={() => {
					props.onSelect(props.node.id);
					// Audio: This is so we can play bespoke SFX on selection of the tech
					const nodeDef: ProgressionTreeNodeDefinition | null = GameInfo.ProgressionTreeNodes.lookup(
						props.node.id,
					);
					if (nodeDef) {
						const event: string =
							"tech-tree-activate-" +
							nodeDef.ProgressionTreeNodeType +
							"_" +
							props.node.currentDepthIndex;
						UI.sendAudioEvent(event);
					}
				}}
				data-tut-highlight="techChooserHighlights"
				node-tree-type={String(props.node.treeType)}
				node-id={String(props.node.id)}
				hotkeyAction="accept"
			>
				<div class="flex flex-col items-stretch pointer-events-none mb-2 relative flex-auto min-w-0">
					<div class="font-title text-xs mt-2\.5 mb-1 mr-2 ml-px uppercase tracking-100 truncate">
						{props.node.name}
					</div>
					<div class="flex flex-row flex-wrap ml-px">
						<For each={currentDepthUnlocks()}>
							{(unlock) => (
								<div class="flex items-stretch w-9 h-9 mr-1\.5 mb-2\.5">
									<img
										src={unlock.icon}
										class="pointer-events-none w-9 h-9"
									/>
								</div>
							)}
						</For>
					</div>
				</div>

				<div class="relative flex flex-col items-end justify-end">
					<div class="flex flex-col grow items-end px-2 pt-2\.5 pb-1\.5 justify-between">
						<div class="flex flex-row justify-end items-center">
							<div class="tree-chooser-item__turns-clock relative pointer-events-none size-8 -top-1\\.5 bg-contain bg-no-repeat bg-center" />
							<div class="font-title text-sm font-bold">{props.node.turns}</div>
						</div>
						<AdvisorRecommendationsList
							recommendations={props.node.recommendations}
							direction="horizontal"
							iconOnly
						/>
					</div>
				</div>

				<Show when={props.node.isLocked}>
					<div class="flex flex-col items-center justify-end my-2 mx-3">
						<div class="font-title text-xs">{pctLabel()}</div>
						<div class="bg-black relative w-11 h-2">
							<div
								class="tree-chooser-item__percent-bar-fill absolute h-full"
								style={{ width: `${props.node.progress ?? 0}%` }}
							/>
						</div>
					</div>
				</Show>
			</ChooserItem>
		</TechCivicTooltip>
	);
};
